Find each row where B=1, read C as the number of consecutive G values to transpose into H onward, and clear/fill H2:S28 while preserving blanks. Normalize whole numeric values to integers and apply the requested fill and center alignment to the answer region. Save the modified workbook to OUT.

```python
import shutil
import openpyxl
from openpyxl.styles import PatternFill, Alignment

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb["Taul1"]
vws = vals["Taul1"]

def clean_value(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        if s == "":
            return None
        try:
            x = float(s)
        except ValueError:
            return s
        return int(x) if x.is_integer() else x
    if isinstance(v, bool):
        return v
    if isinstance(v, float):
        return int(v) if v.is_integer() else v
    return v

def is_one(v):
    if v is None:
        return False
    if isinstance(v, str):
        return v.strip() == "1"
    try:
        return float(v) == 1.0
    except (TypeError, ValueError):
        return False

# Clear the graded answer region first.
for r in range(2, 29):
    for c in range(8, 20):  # H:S
        ws.cell(row=r, column=c).value = None

starts = []
for r in range(2, 29):
    if not is_one(vws.cell(row=r, column=2).value):
        continue
    cval = vws.cell(row=r, column=3).value
    try:
        count = int(float(cval))
    except (TypeError, ValueError):
        count = 0
    starts.append((r, count))
    for i in range(count):
        src_r = r + i
        if src_r > 28:
            break
        val = clean_value(vws.cell(row=src_r, column=7).value)
        tc = 8 + i
        if 8 <= tc <= 19:
            cell = ws.cell(row=r, column=tc)
            cell.value = val

# Apply requested formatting to H2:S28.
fill = PatternFill(start_color="E2EFDA", end_color="E2EFDA", fill_type="solid")
align = Alignment(horizontal="center", vertical="center")
for r in range(2, 29):
    for c in range(8, 20):
        cell = ws.cell(row=r, column=c)
        cell.fill = fill
        cell.alignment = align
        v = cell.value
        if isinstance(v, bool):
            cell.number_format = "General"
        elif isinstance(v, int):
            cell.number_format = "0"
        elif isinstance(v, float):
            cell.number_format = "0.##"
        else:
            cell.number_format = "General"

wb.save(OUT)

print("starts:", starts)
for r in (2, 7, 15):
    print(r, [ws.cell(row=r, column=c).value for c in range(8, 20)])
